import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

layernorm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
__global__ void reduce_kernel(
    const float* __restrict__ x,
    float* __restrict__ partial_sum,
    float* __restrict__ partial_sqsum,
    int N,
    int blocks_per_row)
{
    int batch = blockIdx.y;
    int chunk = blockIdx.x;
    const float* x_b = x + (long)batch * N;
    int tid = threadIdx.x;
    int block_threads = blockDim.x;
    int N4 = N / 4;
    int elems_per_chunk = (N4 + blocks_per_row - 1) / blocks_per_row;
    int start = chunk * elems_per_chunk;
    int end = N4 < (start + elems_per_chunk) ? N4 : (start + elems_per_chunk);
    const float4* x_b4 = reinterpret_cast<const float4*>(x_b);
    float sum = 0.0f;
    float sqsum = 0.0f;
    for (int i = start + tid; i < end; i += block_threads) {
        float4 v = __ldg(&x_b4[i]);
        sum += v.x + v.y + v.z + v.w;
        sqsum += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
    }
    if (chunk == blocks_per_row - 1) {
        int rem_start = N4 * 4;
        for (int i = rem_start + tid; i < N; i += block_threads) {
            float v = __ldg(&x_b[i]);
            sum += v;
            sqsum += v * v;
        }
    }
    unsigned mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
        sqsum += __shfl_down_sync(mask, sqsum, offset);
    }
    __shared__ float warp_sum[32];
    __shared__ float warp_sqsum[32];
    int lane = tid & 31;
    int warp_id = tid >> 5;
    int num_warps = (block_threads + 31) >> 5;
    if (lane == 0) {
        warp_sum[warp_id] = sum;
        warp_sqsum[warp_id] = sqsum;
    }
    __syncthreads();
    if (warp_id == 0) {
        float s = (lane < num_warps) ? warp_sum[lane] : 0.0f;
        float sq = (lane < num_warps) ? warp_sqsum[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            s += __shfl_down_sync(mask, s, offset);
            sq += __shfl_down_sync(mask, sq, offset);
        }
        if (lane == 0) {
            partial_sum[(long)batch * blocks_per_row + chunk] = s;
            partial_sqsum[(long)batch * blocks_per_row + chunk] = sq;
        }
    }
}
__global__ void finalize_kernel(
    const float* __restrict__ partial_sum,
    const float* __restrict__ partial_sqsum,
    float* __restrict__ mean_arr,
    float* __restrict__ invstd_arr,
    int N,
    float eps,
    int batch_size,
    int blocks_per_row)
{
    int b = blockIdx.x;
    if (b >= batch_size) return;
    int tid = threadIdx.x;
    int block_threads = blockDim.x;
    const float* ps = partial_sum + (long)b * blocks_per_row;
    const float* pq = partial_sqsum + (long)b * blocks_per_row;
    float sum = 0.0f;
    float sqsum = 0.0f;
    for (int i = tid; i < blocks_per_row; i += block_threads) {
        sum += ps[i];
        sqsum += pq[i];
    }
    unsigned mask = 0xffffffffu;
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(mask, sum, offset);
        sqsum += __shfl_down_sync(mask, sqsum, offset);
    }
    __shared__ float warp_sum[32];
    __shared__ float warp_sqsum[32];
    int lane = tid & 31;
    int warp_id = tid >> 5;
    int num_warps = (block_threads + 31) >> 5;
    if (lane == 0) {
        warp_sum[warp_id] = sum;
        warp_sqsum[warp_id] = sqsum;
    }
    __syncthreads();
    if (warp_id == 0) {
        float s = (lane < num_warps) ? warp_sum[lane] : 0.0f;
        float sq = (lane < num_warps) ? warp_sqsum[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            s += __shfl_down_sync(mask, s, offset);
            sq += __shfl_down_sync(mask, sq, offset);
        }
        if (lane == 0) {
            float m = s / N;
            float var = sq / N - m * m;
            if (var < 0.0f) var = 0.0f;
            mean_arr[b] = m;
            invstd_arr[b] = rsqrtf(var + eps);
        }
    }
}
__global__ void normalize_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    const float* __restrict__ mean_arr,
    const float* __restrict__ invstd_arr,
    int N,
    int blocks_per_row)
{
    int batch = blockIdx.x;
    int chunk = blockIdx.y;
    int tid = threadIdx.x;
    int block_threads = blockDim.x;
    int N4 = N / 4;
    int elems_per_chunk = (N4 + blocks_per_row - 1) / blocks_per_row;
    int start = chunk * elems_per_chunk;
    int end = N4 < (start + elems_per_chunk) ? N4 : (start + elems_per_chunk);
    const float4* gamma4 = reinterpret_cast<const float4*>(gamma);
    const float4* beta4 = reinterpret_cast<const float4*>(beta);
    const float* x_b = x + (long)batch * N;
    float* out_b = out + (long)batch * N;
    const float4* x_b4 = reinterpret_cast<const float4*>(x_b);
    float4* out_b4 = reinterpret_cast<float4*>(out_b);
    float m = mean_arr[batch];
    float istd = invstd_arr[batch];
    for (int i = start + tid; i < end; i += block_threads) {
        float4 g = __ldg(&gamma4[i]);
        float4 b = __ldg(&beta4[i]);
        float4 v = __ldg(&x_b4[i]);
        float4 r;
        r.x = (v.x - m) * istd * g.x + b.x;
        r.y = (v.y - m) * istd * g.y + b.y;
        r.z = (v.z - m) * istd * g.z + b.z;
        r.w = (v.w - m) * istd * g.w + b.w;
        out_b4[i] = r;
    }
    if (chunk == blocks_per_row - 1) {
        int rem_start = N4 * 4;
        for (int i = rem_start + tid; i < N; i += block_threads) {
            float g = __ldg(&gamma[i]);
            float b = __ldg(&beta[i]);
            float v = __ldg(&x_b[i]);
            out_b[i] = (v - m) * istd * g + b;
        }
    }
}
torch::Tensor layernorm_cuda(
    torch::Tensor x,
    torch::Tensor gamma,
    torch::Tensor beta,
    double eps)
{
    auto x_contig = x.contiguous();
    auto out = torch::empty_like(x_contig);
    int batch_size = x_contig.size(0);
    long N = x_contig.numel() / batch_size;
    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(x_contig.device());
    const int threads = 256;
    int N4 = (int)(N / 4);
    int blocks_per_row = (N4 + (threads * 8) - 1) / (threads * 8);
    if (blocks_per_row < 1) blocks_per_row = 1;
    if (blocks_per_row > 128) blocks_per_row = 128;
    auto partial_sum = torch::empty({(long)batch_size * blocks_per_row}, options);
    auto partial_sqsum = torch::empty({(long)batch_size * blocks_per_row}, options);
    auto mean_arr = torch::empty({batch_size}, options);
    auto invstd_arr = torch::empty({batch_size}, options);
    dim3 grid(blocks_per_row, batch_size);
    reduce_kernel<<<grid, threads>>>(
        x_contig.data_ptr<float>(),
        partial_sum.data_ptr<float>(),
        partial_sqsum.data_ptr<float>(),
        (int)N,
        blocks_per_row
    );
    const int finalize_threads = 128;
    finalize_kernel<<<batch_size, finalize_threads>>>(
        partial_sum.data_ptr<float>(),
        partial_sqsum.data_ptr<float>(),
        mean_arr.data_ptr<float>(),
        invstd_arr.data_ptr<float>(),
        (int)N,
        (float)eps,
        batch_size,
        blocks_per_row
    );
    dim3 norm_grid(batch_size, blocks_per_row);
    normalize_kernel<<<norm_grid, threads>>>(
        x_contig.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        out.data_ptr<float>(),
        mean_arr.data_ptr<float>(),
        invstd_arr.data_ptr<float>(),
        (int)N,
        blocks_per_row
    );
    return out;
}
"""

